#!/usr/bin/env node
'use strict';
/*
 * Safe SEO Manager: deterministic updates only. No LLM, API key, network
 * requests, ranking promises, false reviews, or autogenerated spam articles.
 * npm-free; run: node scripts/seo-manager.cjs --apply | --check | --audit.
 */
const fs=require('node:fs'),path=require('node:path');
const ROOT=path.resolve(__dirname,'..');
const ORIGIN='https://arb-scanner-app.vercel.app';
const DO_NOT_INDEX=new Set(['404.html','account.html','login.html']);
const PRIORITY=[
  'index.html','scanner.html','how-it-works.html','faq.html','bookmakers.html',
  'about.html','pricing.html','contact.html','responsible-gambling.html',
  'privacy.html','terms.html'
];
const SITE_MAP_PATH=path.join(ROOT,'sitemap.xml');
const ROBOTS_PATH=path.join(ROOT,'robots.txt');
const modes=new Set(['--apply','--check','--audit']);
function getTitle(html){
  const x=String(html).match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return x?x[1].replace(/<[^>]*>/g,'').trim():'';
}
function getMeta(html,name){
  const attrs=String(html).match(/<meta\s+[^>]+>/gi)||[];
  for(const tag of attrs){
    const names=[...tag.matchAll(/\b(?:name|property)=["']([^"']+)["']/gi)].map(x=>x[1].toLowerCase());
    if(!names.includes(String(name).toLowerCase()))continue;
    return tag.match(/\bcontent=["']([^"']*)["']/i)?.[1]??'';
  }
  return '';
}
function canonical(html){
  const tags=String(html).match(/<link\s+[^>]+>/gi)||[];
  for(const tag of tags){
    if(!/\brel=["']canonical["']/i.test(tag))continue;
    return tag.match(/\bhref=["']([^"']+)["']/i)?.[1]??'';
  }
  return '';
}
function xmlEscape(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
}
function listPublicHtml(root=ROOT){
  return fs.readdirSync(root).filter(n=>/\.html$/i.test(n)).sort();
}
function pageUrl(filename){
  return filename==='index.html'?ORIGIN+'/':ORIGIN+'/'+encodeURIComponent(filename);
}
function analyze(root=ROOT){
  const pages=listPublicHtml(root),warnings=[],included=[];
  const seenTitles=new Map(),seenCanonicals=new Map();
  for(const name of pages){
    if(DO_NOT_INDEX.has(name))continue;
    const html=fs.readFileSync(path.join(root,name),'utf8');
    if(/\bnoindex\b/i.test(getMeta(html,'robots')))continue;
    const title=getTitle(html),description=getMeta(html,'description'),url=canonical(html);
    if(!title){warnings.push({page:name,reason:'missing-title'});continue}
    if(!description){warnings.push({page:name,reason:'missing-meta-description'});continue}
    if(!url){warnings.push({page:name,reason:'missing-canonical'});continue}
    let expected;
    try{expected=pageUrl(name);if(new URL(url).href!==expected)throw Error('wrong-canonical')}
    catch{warnings.push({page:name,reason:'canonical-not-self-or-host',current:url});continue}
    if(seenCanonicals.has(url)){warnings.push({page:name,reason:'duplicate-canonical',with:seenCanonicals.get(url)});continue}
    seenCanonicals.set(url,name);
    if(seenTitles.has(title.toLowerCase()))warnings.push({page:name,reason:'duplicate-title',with:seenTitles.get(title.toLowerCase())});
    else seenTitles.set(title.toLowerCase(),name);
    // The sitemap must only contain actual discoverable content pages.
    included.push(name);
  }
  const ordered=[...PRIORITY.filter(n=>included.includes(n)),...included.filter(n=>!PRIORITY.includes(n)).sort()];
  return {included:ordered,warnings,excluded:pages.filter(n=>!ordered.includes(n))};
}
function sitemap(included){
  const lines=['<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'];
  for(const name of included)lines.push('  <url><loc>'+xmlEscape(pageUrl(name))+'</loc></url>');
  lines.push('</urlset>');
  return lines.join('\n')+'\n';
}
function robots(){
  return 'User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /account.html\nDisallow: /login.html\n\nSitemap: '+ORIGIN+'/sitemap.xml\n';
}
function run(mode,root=ROOT,write=false){
  if(!modes.has(mode))throw Error('Use --apply, --check, or --audit');
  const analysis=analyze(root);
  const desired={ 'sitemap.xml':sitemap(analysis.included), 'robots.txt':robots()};
  const changed=Object.entries(desired).filter(([filename,value])=>
    !fs.existsSync(path.join(root,filename))||fs.readFileSync(path.join(root,filename),'utf8')!==value)
    .map(([filename])=>filename);
  if(mode==='--apply'&&write)for(const name of changed)fs.writeFileSync(path.join(root,name),desired[name]);
  const result={
    mode,changed,pagesIncluded:analysis.included,pagesExcluded:analysis.excluded,
    recommendations:analysis.warnings,
    status:mode==='--check'&&changed.length?'out-of-date':analysis.warnings.length?'warnings':'clean',
    note:'Sitemap updates never fake lastmod timestamps, create pages or guarantee search rankings.'
  };
  return result;
}
if(require.main===module){
  const mode=process.argv[2]||'--audit';
  try{
    const report=run(mode,ROOT,true);
    fs.mkdirSync(path.join(ROOT,'reports'),{recursive:true});
    fs.writeFileSync(path.join(ROOT,'reports','seo-report.json'),JSON.stringify(report,null,2)+'\n');
    console.log(JSON.stringify(report,null,2));
    if(process.env.GITHUB_STEP_SUMMARY){
      const lines=[
        '## Top Notch Arb SEO Manager',
        'Status: '+report.status,
        'Sitemap pages: '+report.pagesIncluded.length,
        'Changed SEO files: '+(report.changed.join(', ')||'none'),
        'On-page recommendations: '+report.recommendations.length,
        '',
        'Automated edits are limited to canonical sitemap.xml and robots.txt. No AI articles or bookmaker calls.'
      ];
      fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY,lines.join('\n')+'\n');
    }
    if(report.status==='out-of-date')process.exitCode=1;
  }catch(e){console.error(e.message);process.exitCode=1}
}
module.exports={run,analyze,sitemap,robots,canonical,getTitle,getMeta,pageUrl,ORIGIN,DO_NOT_INDEX};
